from pyspark import StorageLevel
from pyspark.sql import functions as F


def with_facts(df, **facts):
    # Adds one column per fact, holding the same value on every row.
    for name, value in facts.items():
        df = df.withColumn(name, F.lit(value))
    return df


def recent_high(ratings):
    picks = ratings.filter((F.col("rating") >= 4.0) & (F.col("rated_at") >= "2026-01-01"))
    return picks.select("user_id", "movie_id", "rating").cache()


def solve(ratings):
    picks = recent_high(ratings)
    # Memory is tight on this job: keep these rows on local disk only.
    picks.persist(StorageLevel.DISK_ONLY)
    picks.count()
    return with_facts(picks, storage=str(picks.storageLevel))
